import React, { useEffect, useState, useRef } from "react";
import * as THREE from "three";
import { Canvas, useThree } from "@react-three/fiber";
import { OrbitControls, Environment, useGLTF } from "@react-three/drei";
import { DecalGeometry } from "three/examples/jsm/geometries/DecalGeometry.js";

// CSS para la animación del spinner
const styleSheet = document.createElement("style");
const REDIRECT_URL = 'https://darkviolet-kangaroo-473589.hostingersite.com/Webpage-JARRON/prueba.html';
const REDIRECT_URL2 = 'https://darkviolet-kangaroo-473589.hostingersite.com/Webpage-JARRON/index.html';
styleSheet.textContent = `
  @keyframes spin {
    0% { transform: rotate(0deg); }
    100% { transform: rotate(360deg); }
  }
`;
document.head.appendChild(styleSheet);

// ====================================================
// ✅ CÁMARA CONTROLADA PARA EXPORTACIÓN
// ====================================================
function ExportCamera({ exportView }) {
  const { camera } = useThree();
  
  useEffect(() => {
    if (exportView) {
      camera.position.set(...exportView.position);
      camera.lookAt(...exportView.target);
      camera.updateProjectionMatrix();
    }
  }, [exportView, camera]);
  
  return null;
}

// ====================================================
// ✅ RENDERIZADOR DE MÚLTIPLES DECALS
// ====================================================
function MultiDecalRenderer({ layers, mainMesh }) {
  const { scene } = useThree();

  useEffect(() => {
    if (!mainMesh || layers.length === 0) return;

    const meshes = [];

    layers.filter(layer => layer.visible).forEach(layer => {
      const { texture, position: posOffset, scale: scaleValue, rotation: rotValue, view } = layer;
      
      // Configura origen y dirección según la vista
      let origin, direction;
      
      if (view === 'front') {
        origin = new THREE.Vector3(posOffset.x * 0.3, 0.3 + posOffset.y * 0.3, 1.5);
        direction = new THREE.Vector3(0, 0, -1);
      } else if (view === 'back') {
        origin = new THREE.Vector3(posOffset.x * 0.3, 0.3 + posOffset.y * 0.3, -1.5);
        direction = new THREE.Vector3(0, 0, 1);
      } else if (view === 'sleeveRight') {
        origin = new THREE.Vector3(1.5, 0.5 + posOffset.y * 0.3, posOffset.x * 0.3);
        direction = new THREE.Vector3(-1, 0, 0);
      } else if (view === 'sleeveLeft') {
        origin = new THREE.Vector3(-1.5, 0.5 + posOffset.y * 0.3, posOffset.x * 0.3);
        direction = new THREE.Vector3(1, 0, 0);
      }
      
      const raycaster = new THREE.Raycaster(origin, direction.normalize());
      const hit = raycaster.intersectObject(mainMesh, true)[0];

      if (!hit) {
        console.warn(`No se encontró intersección en la vista: ${view}`);
        return;
      }

      const normal = hit.face.normal.clone();
      normal.transformDirection(mainMesh.matrixWorld);
      const rot = new THREE.Euler().setFromQuaternion(
        new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 0, 1), normal)
      );
      rot.z += rotValue;

      try {
        const decalGeometry = new DecalGeometry(
          mainMesh,
          hit.point.clone().addScaledVector(normal, 0.01),
          rot,
          new THREE.Vector3(0.35 * scaleValue, 0.35 * scaleValue, 0.35 * scaleValue)
        );

        const decalMaterial = new THREE.MeshStandardMaterial({
          map: texture,
          transparent: true,
          depthTest: true,
          depthWrite: false,
          polygonOffset: true,
          polygonOffsetFactor: -1,
        });

        const decalMesh = new THREE.Mesh(decalGeometry, decalMaterial);
        scene.add(decalMesh);
        meshes.push(decalMesh);
      } catch (err) {
        console.error("Error creando decal:", err);
      }
    });

    return () => {
      meshes.forEach(mesh => scene.remove(mesh));
    };
  }, [layers, mainMesh, scene]);

  return null;
}

// ====================================================
// ✅ MODELO DE LA CAMISETA
// ====================================================
function ModeloCamiseta({ layers, shirtColor }) {
  const { scene } = useGLTF("/models/t-shirt_low_poly.glb");
  const [mainMesh, setMainMesh] = useState(null);

  useEffect(() => {
    if (!scene) return;

    scene.traverse((child) => {
      if (child.isMesh) {
        child.material = child.material.clone();
        child.material.color.set(0xffffff);
        if (!mainMesh) setMainMesh(child);
      }
    });
  }, [scene]);

  // Actualiza el color de la camiseta
  useEffect(() => {
    if (!mainMesh || !shirtColor) return;
    mainMesh.material.color.set(shirtColor);
  }, [mainMesh, shirtColor]);

  return (
    <>
      <primitive object={scene} scale={1.5} />
      {mainMesh && <MultiDecalRenderer layers={layers} mainMesh={mainMesh} />}
    </>
  );
}

// ====================================================
// ✅ PANEL DE CAPAS
// ====================================================
function LayersPanel({ layers, selectedLayer, onSelectLayer, onDeleteLayer, onToggleVisibility }) {
  return (
    <div style={styles.section}>
      <h3 style={styles.sectionTitle}>Capas ({layers.length})</h3>
      <div style={styles.layersList}>
        {layers.length === 0 ? (
          <p style={styles.emptyLayers}>No hay capas. Agrega una imagen o texto.</p>
        ) : (
          layers.map((layer) => (
            <div
              key={layer.id}
              style={{
                ...styles.layerItem,
                ...(selectedLayer === layer.id ? styles.layerItemActive : {})
              }}
              onClick={() => onSelectLayer(layer.id)}
            >
              <div style={styles.layerInfo}>
                <span style={styles.layerIcon}>{layer.type === 'text' ? '✏️' : '🖼️'}</span>
                <div style={styles.layerDetails}>
                  <span style={styles.layerName}>
                    {layer.type === 'text' ? layer.textContent : 'Imagen'}
                  </span>
                  <span style={styles.layerView}>
                    {layer.view === 'front' ? 'Frente' : 
                     layer.view === 'back' ? 'Espalda' : 
                     layer.view === 'sleeveLeft' ? 'Manga Izq' : 'Manga Der'}
                  </span>
                </div>
              </div>
              <div style={styles.layerActions}>
                <button
                  style={styles.layerButton}
                  onClick={(e) => {
                    e.stopPropagation();
                    onToggleVisibility(layer.id);
                  }}
                >
                  {layer.visible ? '👁️' : '👁️‍🗨️'}
                </button>
                <button
                  style={styles.layerButton}
                  onClick={(e) => {
                    e.stopPropagation();
                    onDeleteLayer(layer.id);
                  }}
                >
                  🗑️
                </button>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
}

// ====================================================
// ✅ PANEL 2D DE EDICIÓN
// ====================================================
function Panel2D({ 
  shirtColor,
  onShirtColorChange,
  textConfig,
  onTextConfigChange,
  onGenerateTextTexture,
  selectedView,
  onViewChange,
  layers,
  selectedLayer,
  onSelectLayer,
  onDeleteLayer,
  onToggleVisibility,
  onUpdateLayer,
  currentLayer
}) {
  const canvasRef = useRef();
  const [isDragging, setIsDragging] = useState(false);

  const handleCanvasMouseDown = (e) => {
    if (!currentLayer) return;
    setIsDragging(true);
  };

  const handleCanvasMouseMove = (e) => {
    if (!isDragging || !currentLayer) return;
    
    const rect = e.currentTarget.getBoundingClientRect();
    const x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
    const y = -(((e.clientY - rect.top) / rect.height) * 2 - 1);
    
    onUpdateLayer(currentLayer.id, { position: { x, y } });
  };

  const handleCanvasMouseUp = () => {
    setIsDragging(false);
  };

  const presetPositions = [
    { name: "Centro Pecho", x: 0, y: 0.2 },
    { name: "Centro", x: 0, y: 0 },
    { name: "Izquierda Alta", x: -0.5, y: 0.3 },
    { name: "Derecha Alta", x: 0.5, y: 0.3 },
  ];

  return (
    <div style={styles.panel}>
      <h2 style={styles.title}>Panel de Edición</h2>
      
      {/* Selector de Color de Camiseta */}
      <div style={styles.section}>
        <h3 style={styles.sectionTitle}>Color de Camiseta</h3>
        <div style={styles.colorGrid}>
          {[
            { name: 'Blanco', value: '#ffffff' },
            { name: 'Negro', value: '#000000' },
            { name: 'Gris', value: '#808080' },
            { name: 'Rojo', value: '#e74c3c' },
            { name: 'Azul', value: '#3498db' },
            { name: 'Verde', value: '#27ae60' },
            { name: 'Amarillo', value: '#f1c40f' },
            { name: 'Naranja', value: '#e67e22' },
            { name: 'Morado', value: '#9b59b6' },
            { name: 'Rosa', value: '#ff69b4' },
            { name: 'Azul Marino', value: '#1a237e' },
            { name: 'Verde Oliva', value: '#556b2f' },
          ].map((color, idx) => (
            <button
              key={idx}
              style={{
                ...styles.colorButton,
                background: color.value,
                border: shirtColor === color.value ? '3px solid #ffd700' : '2px solid rgba(255,255,255,0.3)',
              }}
              onClick={() => onShirtColorChange(color.value)}
              title={color.name}
            />
          ))}
        </div>
        <div style={styles.customColorRow}>
          <label style={styles.customColorLabel}>
            Color personalizado:
            <input 
              type="color"
              value={shirtColor}
              onChange={(e) => onShirtColorChange(e.target.value)}
              style={styles.colorPicker}
            />
          </label>
        </div>
      </div>

      {/* Editor de Texto */}
      <div style={styles.section}>
        <h3 style={styles.sectionTitle}>Agregar Texto</h3>
        <input 
          type="text"
          placeholder="Escribe tu texto aquí..."
          value={textConfig.text}
          onChange={(e) => onTextConfigChange({ ...textConfig, text: e.target.value })}
          style={styles.textInput}
          maxLength={50}
        />
        
        <div style={styles.textControlsGrid}>
          <label style={styles.textLabel}>
            Fuente:
            <select 
              value={textConfig.font}
              onChange={(e) => onTextConfigChange({ ...textConfig, font: e.target.value })}
              style={styles.select}
            >
              <option value="Arial">Arial</option>
              <option value="Impact">Impact</option>
              <option value="Georgia">Georgia</option>
              <option value="Courier New">Courier New</option>
              <option value="Comic Sans MS">Comic Sans</option>
              <option value="Verdana">Verdana</option>
            </select>
          </label>

          <label style={styles.textLabel}>
            Tamaño:
            <input 
              type="number"
              min="20"
              max="200"
              value={textConfig.fontSize}
              onChange={(e) => onTextConfigChange({ ...textConfig, fontSize: parseInt(e.target.value) })}
              style={styles.input}
            />
          </label>
        </div>

        <label style={styles.textLabel}>
          Color del texto:
          <input 
            type="color"
            value={textConfig.color}
            onChange={(e) => onTextConfigChange({ ...textConfig, color: e.target.value })}
            style={styles.colorPicker}
          />
        </label>

        <button 
          style={styles.applyTextButton}
          onClick={onGenerateTextTexture}
          disabled={!textConfig.text.trim()}
        >
          ✏️ Aplicar Texto
        </button>
      </div>
      
      {/* Selector de Vista */}
      <div style={styles.section}>
        <h3 style={styles.sectionTitle}>Vista Activa</h3>
        <div style={styles.buttonGroup}>
          <button 
            style={{...styles.button, ...(selectedView === 'front' ? styles.buttonActive : {})}}
            onClick={() => onViewChange('front')}
          >
            Frente
          </button>
          <button 
            style={{...styles.button, ...(selectedView === 'back' ? styles.buttonActive : {})}}
            onClick={() => onViewChange('back')}
          >
            Espalda
          </button>
        </div>
        <div style={{...styles.buttonGroup, marginTop: '8px'}}>
          <button 
            style={{...styles.button, ...(selectedView === 'sleeveLeft' ? styles.buttonActive : {})}}
            onClick={() => onViewChange('sleeveLeft')}
          >
            Manga Izq
          </button>
          <button 
            style={{...styles.button, ...(selectedView === 'sleeveRight' ? styles.buttonActive : {})}}
            onClick={() => onViewChange('sleeveRight')}
          >
            Manga Der
          </button>
        </div>
      </div>

      {/* Panel de Capas */}
      <LayersPanel 
        layers={layers}
        selectedLayer={selectedLayer}
        onSelectLayer={onSelectLayer}
        onDeleteLayer={onDeleteLayer}
        onToggleVisibility={onToggleVisibility}
      />

      {/* Canvas 2D Interactivo */}
      {currentLayer && (
        <>
          <div style={styles.section}>
            <h3 style={styles.sectionTitle}>Editar Capa Seleccionada</h3>
            <div 
              ref={canvasRef}
              style={styles.canvas2D}
              onMouseDown={handleCanvasMouseDown}
              onMouseMove={handleCanvasMouseMove}
              onMouseUp={handleCanvasMouseUp}
              onMouseLeave={handleCanvasMouseUp}
            >
              <div style={styles.shirtOutline}>
                {currentLayer.previewUrl && (
                  <img 
                    src={currentLayer.previewUrl}
                    alt="Preview"
                    style={{
                      ...styles.logoPreview,
                      left: `${(currentLayer.position.x + 1) * 50}%`,
                      top: `${(-currentLayer.position.y + 1) * 50}%`,
                      transform: `translate(-50%, -50%) scale(${currentLayer.scale}) rotate(${currentLayer.rotation}rad)`,
                    }}
                    draggable={false}
                  />
                )}
              </div>
              <p style={styles.hint}>Arrastra para mover</p>
            </div>
          </div>

          {/* Posiciones Predefinidas */}
          <div style={styles.section}>
            <h3 style={styles.sectionTitle}>Posiciones Rápidas</h3>
            <div style={styles.presetGrid}>
              {presetPositions.map((preset, idx) => (
                <button
                  key={idx}
                  style={styles.presetButton}
                  onClick={() => onUpdateLayer(currentLayer.id, { position: { x: preset.x, y: preset.y } })}
                >
                  {preset.name}
                </button>
              ))}
            </div>
          </div>

          {/* Controles de Escala */}
          <div style={styles.section}>
            <h3 style={styles.sectionTitle}>Tamaño</h3>
            <input 
              type="range"
              min="0.5"
              max="2"
              step="0.1"
              value={currentLayer.scale}
              onChange={(e) => onUpdateLayer(currentLayer.id, { scale: parseFloat(e.target.value) })}
              style={styles.slider}
            />
            <span style={styles.value}>{currentLayer.scale.toFixed(1)}x</span>
          </div>

          {/* Controles de Rotación */}
          <div style={styles.section}>
            <h3 style={styles.sectionTitle}>Rotación</h3>
            <input 
              type="range"
              min="0"
              max={Math.PI * 2}
              step="0.1"
              value={currentLayer.rotation}
              onChange={(e) => onUpdateLayer(currentLayer.id, { rotation: parseFloat(e.target.value) })}
              style={styles.slider}
            />
            <span style={styles.value}>{Math.round(currentLayer.rotation * 180 / Math.PI)}°</span>
          </div>

          {/* Posición Manual */}
          <div style={styles.section}>
            <h3 style={styles.sectionTitle}>Posición Precisa</h3>
            <div style={styles.inputRow}>
              <label style={styles.label}>
                X:
                <input 
                  type="number"
                  min="-1"
                  max="1"
                  step="0.05"
                  value={currentLayer.position.x.toFixed(2)}
                  onChange={(e) => onUpdateLayer(currentLayer.id, { 
                    position: { ...currentLayer.position, x: parseFloat(e.target.value) }
                  })}
                  style={styles.input}
                />
              </label>
              <label style={styles.label}>
                Y:
                <input 
                  type="number"
                  min="-1"
                  max="1"
                  step="0.05"
                  value={currentLayer.position.y.toFixed(2)}
                  onChange={(e) => onUpdateLayer(currentLayer.id, { 
                    position: { ...currentLayer.position, y: parseFloat(e.target.value) }
                  })}
                  style={styles.input}
                />
              </label>
            </div>
          </div>
        </>
      )}
    </div>
  );
}

// ====================================================
// ✅ ESCENA PRINCIPAL
// ====================================================
export default function Camiseta3D() {
  const [selectedView, setSelectedView] = useState('front');
  const [shirtColor, setShirtColor] = useState('#ffffff');
  const [layers, setLayers] = useState([]);
  const [selectedLayer, setSelectedLayer] = useState(null);
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [isExporting, setIsExporting] = useState(false);
  const [exportView, setExportView] = useState(null);
  const canvasRef = useRef();
  const [textConfig, setTextConfig] = useState({
    text: '',
    font: 'Arial',
    fontSize: 80,
    color: '#000000'
  });

  const handleImageUpload = (e) => {
    const file = e.target.files[0];
    if (!file) return;

    const url = URL.createObjectURL(file);
    
    const loader = new THREE.TextureLoader();
    loader.load(url, (tex) => {
      tex.flipY = false;
      tex.colorSpace = THREE.SRGBColorSpace;
      
      const newLayer = {
        id: Date.now(),
        type: 'image',
        texture: tex,
        previewUrl: url,
        position: { x: 0, y: 0.2 },
        scale: 1,
        rotation: 0,
        view: selectedView,
        visible: true
      };
      
      setLayers([...layers, newLayer]);
      setSelectedLayer(newLayer.id);
    });
  };

  const handleGenerateTextTexture = () => {
    if (!textConfig.text.trim()) return;

    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    
    canvas.width = 1024;
    canvas.height = 512;
    
    ctx.fillStyle = 'rgba(0, 0, 0, 0)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    
    ctx.font = `bold ${textConfig.fontSize}px ${textConfig.font}`;
    ctx.fillStyle = textConfig.color;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    
    ctx.fillText(textConfig.text, canvas.width / 2, canvas.height / 2);
    
    const textureUrl = canvas.toDataURL();
    
    const loader = new THREE.TextureLoader();
    loader.load(textureUrl, (tex) => {
      tex.flipY = false;
      tex.colorSpace = THREE.SRGBColorSpace;
      
      const newLayer = {
        id: Date.now(),
        type: 'text',
        textContent: textConfig.text,
        texture: tex,
        previewUrl: textureUrl,
        position: { x: 0, y: 0.2 },
        scale: 1,
        rotation: 0,
        view: selectedView,
        visible: true
      };
      
      setLayers([...layers, newLayer]);
      setSelectedLayer(newLayer.id);
      setTextConfig({ ...textConfig, text: '' });
    });
  };

  const handleUpdateLayer = (layerId, updates) => {
    setLayers(layers.map(layer => 
      layer.id === layerId ? { ...layer, ...updates } : layer
    ));
  };

  const handleDeleteLayer = (layerId) => {
    setLayers(layers.filter(layer => layer.id !== layerId));
    if (selectedLayer === layerId) {
      setSelectedLayer(null);
    }
  };

  const handleToggleVisibility = (layerId) => {
    setLayers(layers.map(layer => 
      layer.id === layerId ? { ...layer, visible: !layer.visible } : layer
    ));
  };

  const handleExport = async () => {
    setIsExporting(true);
    
    try {
      const views = [
        { name: 'frente', position: [0, 0.5, 3], target: [0, 0, 0] },
        { name: 'espalda', position: [0, 0.5, -3], target: [0, 0, 0] },
        { name: 'manga-derecha', position: [3, 0.5, 0], target: [0, 0, 0] },
        { name: 'manga-izquierda', position: [-3, 0.5, 0], target: [0, 0, 0] }
      ];

      const captures = [];

      // Capturar cada vista
      for (let i = 0; i < views.length; i++) {
        const view = views[i];
        setExportView(view);
        
        // Esperar a que se renderice completamente
        await new Promise(resolve => setTimeout(resolve, 1000));
        
        // Capturar el canvas usando el método correcto
        const canvas = document.querySelector('canvas');
        if (canvas) {
          // Forzar un render adicional
          await new Promise(resolve => requestAnimationFrame(resolve));
          await new Promise(resolve => requestAnimationFrame(resolve));
          
          const imageData = canvas.toDataURL('image/png', 1.0);
          captures.push({
            name: view.name,
            data: imageData
          });
        }
      }

      // Descargar todas las capturas con delay
      for (let i = 0; i < captures.length; i++) {
        await new Promise(resolve => setTimeout(resolve, 200));
        const capture = captures[i];
        const link = document.createElement('a');
        link.download = `camiseta-${capture.name}-${Date.now()}.png`;
        link.href = capture.data;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
      }

      // Descargar las imágenes y textos originales
      const imageCount = layers.filter(l => l.type === 'image').length;
      const textCount = layers.filter(l => l.type === 'text').length;
      
      layers.forEach((layer, index) => {
        setTimeout(() => {
          if (layer.previewUrl) {
            const link = document.createElement('a');
            const fileName = layer.type === 'image' 
              ? `imagen-original-${index + 1}-${Date.now()}.png`
              : `texto-${layer.textContent}-${Date.now()}.png`;
            link.download = fileName;
            link.href = layer.previewUrl;
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
          }
        }, (index + captures.length) * 200);
      });

      // Esperar a que terminen todas las descargas y luego redirigir
      const totalTime = (captures.length + layers.length) * 200 + 1500;
      
      setTimeout(() => {
        alert(`✅ Exportación completada!\n\nSe descargaron:\n- 4 renders (Frente, Espalda, Manga Der, Manga Izq)\n- ${imageCount} imagen(es) original(es)\n- ${textCount} texto(s)\n\nSerás redirigido en un momento...`);
        
        // Redirigir después de 2 segundos
        setTimeout(() => {
          window.location.href = REDIRECT_URL;
        }, 2000);
      }, totalTime);
      
    } catch (error) {
      console.error('Error al exportar:', error);
      alert('❌ Error al exportar el diseño. Por favor intenta de nuevo.');
      setIsExporting(false);
      setExportView(null);
    }
  };

  const currentLayer = layers.find(l => l.id === selectedLayer);

  // Detectar tamaño de pantalla
  const [isMobile, setIsMobile] = useState(window.innerWidth <= 768);
  
  useEffect(() => {
    const handleResize = () => {
      const mobile = window.innerWidth <= 768;
      setIsMobile(mobile);
      if (mobile) {
        setSidebarOpen(false);
      }
    };
    
    window.addEventListener('resize', handleResize);
    handleResize();
    
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  return (
    <div style={styles.container}>
      {/* Botón hamburguesa para móviles */}
      {isMobile && (
        <button 
          style={{
            ...styles.hamburgerButton,
            left: sidebarOpen ? '320px' : '10px',
          }}
          onClick={() => setSidebarOpen(!sidebarOpen)}
        >
          {sidebarOpen ? '✕' : '☰'}
        </button>
      )}

      {/* Panel Lateral */}
      <div style={{
        ...styles.sidebar,
        ...(isMobile ? styles.sidebarMobile : {}),
        transform: isMobile && !sidebarOpen ? 'translateX(-100%)' : 'translateX(0)',
      }}>
        <div style={styles.uploadSection}>
          <button 
            style={styles.backButton}
            onClick={() => window.location.href = REDIRECT_URL2}
          >
            ← Volver
          </button>
          <label style={styles.uploadButton}>
            📁 Subir Imagen
            <input
              type="file"
              onChange={handleImageUpload}
              accept="image/*"
              style={{ display: 'none' }}
            />
          </label>
          <button 
            style={{
              ...styles.exportButton,
              opacity: layers.length === 0 ? 0.5 : 1,
              cursor: layers.length === 0 ? 'not-allowed' : 'pointer'
            }} 
            onClick={handleExport}
            disabled={layers.length === 0}
          >
            💾 Exportar Diseño {layers.length > 0 && `(${layers.length})`}
          </button>
        </div>
        
        <Panel2D 
          shirtColor={shirtColor}
          onShirtColorChange={setShirtColor}
          textConfig={textConfig}
          onTextConfigChange={setTextConfig}
          onGenerateTextTexture={handleGenerateTextTexture}
          selectedView={selectedView}
          onViewChange={setSelectedView}
          layers={layers}
          selectedLayer={selectedLayer}
          onSelectLayer={setSelectedLayer}
          onDeleteLayer={handleDeleteLayer}
          onToggleVisibility={handleToggleVisibility}
          onUpdateLayer={handleUpdateLayer}
          currentLayer={currentLayer}
        />
      </div>

      {/* Vista 3D */}
      <div style={styles.canvas3DContainer}>
        {isExporting && (
          <div style={styles.exportingOverlay}>
            <div style={styles.exportingMessage}>
              <div style={styles.spinner}></div>
              <p>Exportando vistas...</p>
              <p style={styles.exportingSubtext}>
                {exportView ? `Capturando: ${exportView.name}` : 'Preparando...'}
              </p>
            </div>
          </div>
        )}
        
        <Canvas
          ref={canvasRef}
          camera={{ position: [0, 0.5, 3], fov: 35 }}
          style={{ width: "100%", height: "100%" }}
          gl={{ 
            preserveDrawingBuffer: true,
            antialias: true,
            alpha: false
          }}
        >
          <color attach="background" args={['#f0f0f0']} />
          <ambientLight intensity={0.8} />
          <directionalLight position={[2, 2, 5]} intensity={1.5} />
          <directionalLight position={[-2, -2, -5]} intensity={0.5} />
          <Environment preset="studio" />
          
          {!isExporting && <OrbitControls enableZoom={true} />}
          {isExporting && exportView && <ExportCamera exportView={exportView} />}

          <group position={[0, -0.6, 0]}>
            <ModeloCamiseta layers={layers} shirtColor={shirtColor} />
          </group>
        </Canvas>
      </div>
    </div>
  );
}

